def rrf(lists, k=60):
    scores = {}
    for hits in lists:
        for rank, chunk_id in enumerate(hits, start=1):
            scores[chunk_id] = scores.get(chunk_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda item: item[1], reverse=True)

dense = ["migration-guide", "vector-dimensions", "pgvector-overview"]
sparse = ["err-embed-dim", "vector-dimensions", "changelog"]

for chunk_id, score in rrf([dense, sparse]):
    print(chunk_id, round(score, 5))
